    // Add spin class
    ['dice', 'diceInlineView'].forEach(id => {
      const el = document.getElementById(id);
      if(el) el.classList.add('rolling');
    });
    
    const result = await _rollDice.apply(this, arguments);
    
    // After roll, get the actual number from state
